//! The contract with a program that runs the core: the types generated from the schema in
//! `contract/immune/v1/`, and the one piece of hand-written code their JSON needs.
//!
//! `contract/immune.v1.rs` is generated by prost-build and committed, so building the program
//! needs no generator. The test `the_committed_types_are_what_the_schema_gives` in
//! `tests/contract.rs` generates it again from the schema and fails when the two differ. It is
//! brought in with `include!`, which rustfmt does not follow, and the lints that generated
//! code does not keep are allowed on its module only.
//!
//! JSON comes from serde derives that the generator puts on every message and enum. prost keeps
//! an enum field as an `i32`, which serde would print as a number; the generator gives every
//! such field the functions below, so it prints as the name of its value. They are generic over
//! the enum, so no field has code of its own.

#[allow(dead_code, clippy::all, clippy::pedantic)]
pub mod v1 {
    include!("contract/immune.v1.rs");
}

use serde::de::{DeserializeOwned, IntoDeserializer};
use serde::{Deserialize, Deserializer, Serialize, Serializer};

/// The enum value a store's word names, by the same names the JSON uses (`no_reader` is
/// `CAUSE_NO_READER`); the enum's unspecified value, 0, for a word it does not have.
pub fn value_of<E>(word: &str) -> i32
where
    E: DeserializeOwned + Into<i32>,
{
    let d: serde::de::value::StrDeserializer<serde::de::value::Error> = word.into_deserializer();
    E::deserialize(d).map_or(0, Into::into)
}

/// An enum field as the name of its value. A number this build does not know is refused rather
/// than printed as a number.
pub fn enum_name<E, S>(value: &i32, s: S) -> Result<S::Ok, S::Error>
where
    E: TryFrom<i32> + Serialize,
    S: Serializer,
{
    match E::try_from(*value) {
        Ok(e) => e.serialize(s),
        Err(_) => Err(serde::ser::Error::custom(format!(
            "{value} is not a value of this enum"
        ))),
    }
}

/// An enum field from the name of its value. A word this build does not know reads as the
/// enum's unspecified value, so that a value added to the schema later does not make an older
/// reader fail on the whole message; the schema says how each enum reads that value.
pub fn enum_from_name<'de, E, D>(d: D) -> Result<i32, D::Error>
where
    E: DeserializeOwned + Into<i32>,
    D: Deserializer<'de>,
{
    String::deserialize(d).map(|word| value_of::<E>(&word))
}

/// An optional enum field as the name of its value, or null.
pub fn optional_enum_name<E, S>(value: &Option<i32>, s: S) -> Result<S::Ok, S::Error>
where
    E: TryFrom<i32> + Serialize,
    S: Serializer,
{
    match value {
        Some(v) => enum_name::<E, S>(v, s),
        None => s.serialize_none(),
    }
}

/// An optional enum field from the name of its value, or null. A word this build does not know
/// reads as the enum's unspecified value, as in `enum_from_name`.
pub fn optional_enum_from_name<'de, E, D>(d: D) -> Result<Option<i32>, D::Error>
where
    E: DeserializeOwned + Into<i32>,
    D: Deserializer<'de>,
{
    Option::<String>::deserialize(d).map(|word| word.map(|w| value_of::<E>(&w)))
}

/// Text from a source as the contract gives it: each character `hidden` names, and the
/// backslash itself, written as `\u{...}`. Escaping the backslash makes the shown form unique:
/// a name holding a hidden character and a name that spells its escape out are shown apart, and
/// `unescape` gives back exactly what was escaped. `hidden` is the core's own test of a character
/// that could hide or rearrange what is shown (`icu::hidden`); it is passed in so that this file
/// needs nothing else of the core.
pub fn escape(s: &str, hidden: impl Fn(char) -> bool) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        if c == '\\' || hidden(c) {
            out.extend(c.escape_unicode());
        } else {
            out.push(c);
        }
    }
    out
}

/// Text as `escape` shows it, back as it was: every `\u{...}` that names a character becomes
/// that character, and anything else is kept as written. An id the core printed asks back the
/// same thing.
pub fn unescape(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    let mut rest = s;
    while let Some(at) = rest.find("\\u{") {
        out.push_str(&rest[..at]);
        let after = &rest[at + 3..];
        // Hex digits alone: `from_str_radix` would also take a sign.
        let named = after.split_once('}').and_then(|(hex, tail)| {
            hex.bytes()
                .all(|b| b.is_ascii_hexdigit())
                .then(|| u32::from_str_radix(hex, 16).ok().and_then(char::from_u32))
                .flatten()
                .map(|c| (c, tail))
        });
        match named {
            Some((c, tail)) => {
                out.push(c);
                rest = tail;
            }
            None => {
                out.push('\\');
                rest = &rest[at + 1..];
            }
        }
    }
    out.push_str(rest);
    out
}
